 let sheets={};
 function load(prefix='assets/'){
  sheets={};for(const [name,spec] of Object.entries(layout)){const image=new root.Image();image.crossOrigin="anonymous";image.src=prefix+spec.file;sheets[name]=image;}return sheets;
 }
 function setSheets(value){sheets=value;}
 function ready(form){return Object.entries(layout).filter(([name])=>name.startsWith(form+'-')).every(([name])=>{const im=sheets[name];return !!im&&(im.complete??true)&&(im.naturalWidth??im.width)>0;});}
 function selectFrame(form,id,elapsed,duration){
  const t=Math.max(0,elapsed),end=duration-t;
  if(id==='slow'||id==='fast'){
   if(t<220||end<200)return 0;
   const times=id==='fast'?[100,85,95,85,100,95]:[250,220,260,220,260,240];
   let phase=(t-220)%times.reduce((a,b)=>a+b,0);for(let i=0;i<times.length;i++){if(phase<times[i])return i;phase-=times[i];}return 0;
  }
  if(['nod','shake','greet','tail'].includes(id)||id==='smile'){
   if(end<180)return 5;
   const times=id==='smile'?[380,850,70,90,230,480]:id==='greet'?[200,220,240,400,220,280]:[180,160,180,220,180,240];
   let phase=t%times.reduce((a,b)=>a+b,0);for(let i=0;i<6;i++){if(phase<times[i])return i;phase-=times[i];}
  }
  if(id==='unroll'){
   const stages=[[0,240],[1,270],[2,330],[3,1100],[4,150],[5,700],[3,220],[2,330],[1,270],[0,Infinity]];let phase=t;for(const [frame,ms] of stages){if(phase<ms)return frame;phase-=ms;}
  }
  if(id==='roll'){const times=[360,420,420,550,550,Infinity];let phase=t;for(let i=0;i<6;i++){if(phase<times[i])return i;phase-=times[i];}}
  const expression=['smile','laugh','shy','surprise','puzzled','serious','sleepy','comfort','typo','idea','relief'].includes(id);
  const timeline=expression?[300,400,Math.max(450,duration-1550),130,400,320]:id==='stretch'?[240,260,340,850,340,Infinity]:id==='rub'?[300,400,650,Math.max(450,duration-2120),450,320]:[320,430,530,Math.max(480,duration-2250),520,450];
  let phase=t;for(let i=0;i<6;i++){if(phase<timeline[i])return i;phase-=timeline[i];}return 5;
 }
 function pose(ctx,form,id,frame){
  const [sheet,row]=stateRows[form][id],f=layout[sheet].rows[row][frame],im=sheets[sheet];
  const [sx,sy,sw,sh]=f.source,[dx,dy,dw,dh]=f.destination;
  ctx.save();ctx.translate(dx,dy);ctx.scale(dw/sw,dh/sh);ctx.beginPath();
  for(const points of f.clip){points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();}ctx.clip();
  ctx.drawImage(im,sx,sy,sw,sh,0,0,sw,sh);ctx.restore();
 }
 function draw(ctx,form,id,elapsed,duration,cutoff){
  const frame=selectFrame(form,id,elapsed,duration);
  if(form==='classic')pose(ctx,form,id,frame);
  else if(id==='slow'||id==='fast'){
   // One continuous lower-body region avoids rectangular cuts through cuffs and sleeves.
   pose(ctx,form,id,0);ctx.save();ctx.beginPath();ctx.rect(0,325,512,69);ctx.clip();ctx.clearRect(0,325,512,69);pose(ctx,form,id,frame);ctx.restore();
  }else pose(ctx,form,id,frame);
  return frame;
 }
 const api={layout,stateRows,load,setSheets,ready,selectFrame,pose,draw};
 if(typeof module==='object'&&module.exports)module.exports=api;else root.JieFrames=api;
